settings.custom_css:
.m-store-info {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  column-gap: 70px;
  row-gap: 70px;
  margin-top: 50px;
}

.m-store-info__item a {
  text-decoration: underline;
}

.m-store-info__item h4 {
  line-height: 26px;
  margin-bottom: 10px;
}

.m-store-info__item ul {
  display: flex;
  align-items: center;
  margin: 0 -15px;
  margin-top: 20px;
}

.m-store-info__item ul li {
  padding: 0 15px;
}

@media (max-width: 767px) {
  .m-store-info {
    grid-template-columns: auto;
    row-gap: 20px;
    margin-top: 10px;
  }
}
@media (min-width: 768px) {
  .m-store-info {
    column-gap: 50px;
    row-gap: 40px;
    margin-top: 30px;
  }
}
@media (min-width: 1024px) {
  .m-store-info {
    column-gap: 30px;
    row-gap: 30px;
    margin-top: 30px;
  }
}

.m-store-info-custom {
  display: flex;
  flex-direction: column;
}

.m-store-column{
margin: 20px 0px;
}

.m-store-item{
margin: 20px 0px;
}

.m-store-item h4 {
  font-size: 13px !important;
  font-weight: 700 !important;
  text-transform: uppercase;
  margin-bottom: 8px !important;
  color: #000000;
  letter-spacing: 0.5px;
}

.m-store-item p {
  font-size: 13px;
  color: #555555;
  line-height: 1.6;
  margin-bottom: 0 !important;
}

.m-store-link {
  display: inline-block;
  font-size: 13px;
  color: #000000;
  text-decoration: underline;
  text-underline-offset: 4px;
  transition: color 0.3s ease;
}
.m-store-link:hover { color: #E6007E; }

.m-wa-link-wrapper {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-top: 10px;
}

.m-wa-btn {
  display: inline-flex;
  align-items: flex-start;
  gap: 8px;
  font-size: 13px;
  color: #333333;
  text-decoration: none;
  line-height: 1.4;
  white-space: nowrap; 
  transition: color 0.3s ease;
}

.m-wa-btn i {
  color: #25d366;
  font-size: 16px;
  margin-top: 1px;
  flex-shrink: 0; 
}
.m-wa-btn:hover, .m-wa-btn:hover i { color: #1da851; }
